#!/usr/bin/env python3
"""Week 5 · harness for Task 3. Do not edit this file.

A synthetic web-like graph: power-law out-degrees, a few dead ends, one small
trap. Fixed seed, so everybody's numbers compare.

    nodes      1,200
    edges      about 6,000  (density under 0.5%)
    scored     wall time, and the floats you held
    checked    every rank within 1e-9 of the dense answer

    python3 bench.py
    python3 bench.py --yours
"""
import argparse, random, time

SEED, NODES, AVG_OUT = 246, 1_200, 5


def build(seed=SEED):
    rng = random.Random(seed)
    nodes = [f"p{i:05d}" for i in range(NODES)]
    # preferential attachment, so in-degrees are heavy-tailed like the real web
    targets = list(nodes[:10])
    graph = {}
    for v in nodes:
        k = max(0, min(int(rng.paretovariate(1.6)) + AVG_OUT - 2, 40))
        outs = set()
        while len(outs) < k:
            outs.add(rng.choice(targets))
        outs.discard(v)
        graph[v] = sorted(outs)
        targets.extend(graph[v] or [v])
        targets.append(v)
    # a handful of dead ends
    for v in rng.sample(nodes, 12):
        graph[v] = []
    # one small spider trap
    a, b = nodes[-1], nodes[-2]
    graph[a], graph[b] = [b], [a]
    return graph


def run(cls, label, graph, reference=None):
    solver = cls()
    solver._n = len(graph)
    t0 = time.perf_counter()
    ranks = solver.run(graph)
    elapsed = time.perf_counter() - t0
    floats = solver.memory_floats()

    worst = 0.0
    if reference is not None:
        worst = max(abs(ranks[v] - reference[v]) for v in reference)
    total = sum(ranks.values())
    print(f"  {label:<10} {elapsed:>7.2f}s   floats held {floats:>12,}   "
          f"sum {total:.6f}"
          + (f"   worst diff {worst:.2e}" if reference is not None else ""))
    return {"time": elapsed, "floats": floats, "ranks": ranks, "worst": worst}


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--yours", action="store_true")
    a = p.parse_args()

    graph = build()
    edges = sum(len(o) for o in graph.values())
    print(f"\n  {len(graph):,} nodes, {edges:,} edges, "
          f"density {edges / len(graph) ** 2:.4%}\n")

    from task3_sparse import DenseMatrix
    base = run(DenseMatrix, "baseline", graph)

    if a.yours:
        from task3_sparse import YourPageRank
        mine = run(YourPageRank, "yours", graph, base["ranks"])
        print()
        if mine["worst"] > 1e-9:
            print(f"   FAIL  ranks differ by {mine['worst']:.2e}, tolerance is 1e-9.")
        else:
            speed = base["time"] / mine["time"]
            mem = base["floats"] / max(mine["floats"], 1)
            print(f"   ok    ranks match to 1e-9")
            print(f"   {speed:>6.1f}x faster   {mem:>7.1f}x less memory")
            grade = ("strong" if mem >= 100 and speed >= 5 else
                     "good" if mem >= 20 and speed >= 2 else
                     "pass" if mem > 2 else "not yet")
            print(f"\n   -> {grade}")
    print()


if __name__ == "__main__":
    main()
